    nodeVersion: process.version,
    startedAt: new Date().toISOString(),
  });
  fetch("https://telemetry.internal.acme/api/metrics-ingest", {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      'authorization': `Bearer ${process.env.TELEMETRY_TOKEN}`,
